void mainImage(out vec4 couleurFragment, vec2 coordonneeFragment) {
    float tempsActuel = iTime;
    vec2 resolutionEcran = iResolution.xy;

    vec2 coordonneesUV = (coordonneeFragment + coordonneeFragment - resolutionEcran) / resolutionEcran.y;
    vec2 grilleEchelle = coordonneesUV * (3.0 + sin(tempsActuel * 0.5));

    vec2 indexCellule = floor(grilleEchelle);
    vec2 coordonneeLocale = (fract(grilleEchelle) - 0.5) * mat2(cos(tempsActuel * 0.05 + vec4(0.0, 11.0, 33.0, 0.0)));

    float rayonPolaire = length(coordonneeLocale);
    float anglePolaire = atan(coordonneeLocale.y, coordonneeLocale.x);

    float masqueArcCercle = smoothstep(1.0, 0.8, abs(anglePolaire + 1.0));
    float valeurOscillationCellule = 0.5 + 0.5 * sin(tempsActuel * 3.0 + indexCellule.x + indexCellule.y);

    float contourCercleInterne = smoothstep(0.025, 0.005, abs(rayonPolaire - 0.275)) 
                               * mix(masqueArcCercle, 1.0 - masqueArcCercle, valeurOscillationCellule);

    float masqueDisquePrincipal = smoothstep(0.46, 0.44, rayonPolaire);

    vec2 coordonneeSymetrique = vec2(abs(coordonneeLocale.x), coordonneeLocale.y);
    vec2 offsetYeux = 0.15 + 0.05 * vec2(cos(tempsActuel * 2.0 + indexCellule.y), sin(tempsActuel * 5.0 + indexCellule.x));
    float masquePupilles = smoothstep(0.08, 0.06, length(coordonneeSymetrique - offsetYeux));

    float masqueElementsFaces = min(masquePupilles + contourCercleInterne, 1.0);

    vec4 couleurFondTeinte = 0.08 + 0.14 * clamp(abs(mod(tempsActuel * 0.18 + vec4(0.0, 4.0, 2.0, 0.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    vec4 couleurJauneFace = vec4(1.0, 0.92, 0.2, 0.0) * (1.0 - masqueElementsFaces);

    float vignettageBordure = smoothstep(3.0, 1.0, length(coordonneesUV));

    couleurFragment = mix(couleurFondTeinte, couleurJauneFace, masqueDisquePrincipal) * vignettageBordure;
}
